def bytes_scanned(row_groups, widths, projected, predicate=None, layout="column"):
    groups_read = 0
    total = 0
    for group in row_groups:
        rows = group["rows"]
        if layout == "row":
            groups_read += 1
            total += rows * sum(widths.values())
            continue
        if predicate is not None:
            column, lo, hi = predicate
            stats = group.get("stats", {}).get(column)
            if stats is not None and (stats[1] < lo or stats[0] > hi):
                continue
        groups_read += 1
        columns = set(projected)
        if predicate is not None:
            columns.add(predicate[0])
        total += rows * sum(widths[c] for c in columns)
    return {"groups_read": groups_read, "bytes": total}
